mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.HAP_CREDIT_AMT as hapCreditAmt, C.CUSTOMER_NAME as customerName, D.INSITITUTE_CODE as insitituteCode ,A.IS_INTERBANK as isInterbank ,A.IS_LOOP_AMT as isLoopAmt ,case when G.CREDIT_TYPE = '13' then G.CREDIT_AMT/100000000 else null end as nlpscreditline FROM CREDIT_LINES A left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID left join ( select B.CUSTOMER_ID,B.PFLSH,B.CREDIT_AMT,F.CREDIT_TYPE from CREDIT_LINES B left join CREDIT_CONF_INFO E on B.CREDIT_MST_ID = E.CREDIT_MST_ID left join CREDIT_TAG_INFO F on E.CREDIT_TAG_ID = F.CREDIT_TAG_ID where F.CREDIT_TYPE = '13' ) G on A.CUSTOMER_ID = G.CUSTOMER_ID AND A.PFLSH = G.PFLSH
A.CREDIT_MST_ID = '0001'
AND A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE CONCAT(CONCAT('%',#{pflsh}),'%')
AND to_char(A.VDATE,'yyyy-MM-dd') > = #{vdate,jdbcType=DATE}
AND to_char(A.VDATE,'yyyy-MM-dd') < = #{mdate,jdbcType=DATE}
AND A.IS_INTERBANK = #{isInterbank,jdbcType=VARCHAR}

		SELECT
	 		count(1)
	 	FROM
	 		CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
        AND A.Credit_Type='01'

            and A.VDATE= to_date(#{vdate},'yyyy-MM-dd')


			AND A.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


			 and  SEQNO <> #{seqno}


            AND A.pflsh = #{pflsh,jdbcType=VARCHAR}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
        /** modify by yanya on 20190930 去除主体客户编号为空判断
         and PARENT_CUSTOMER_ID IS NULL 
          **/

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES 
        where PFLSH = #{pflsh,jdbcType=VARCHAR}


			 and  SEQNO <> #{seqno}


			and CREDIT_MST_ID=#{creditMstId}

        SELECT
            count(1)
        FROM CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

			AND A.Credit_Type = #{creditType,jdbcType=VARCHAR}


            and A.VDATE= to_date(#{vdate},'yyyy-MM-dd')


            AND A.CREDIT_MST_ID = #{creditMstId,jdbcType=VARCHAR}


            and  SEQNO != #{seqno,jdbcType=VARCHAR}


            AND A.pflsh = #{pflsh,jdbcType=VARCHAR}

SELECT distinct i.CUSTOMER_ID AS id, i.CUSTOMER_NAME AS text, a.INDUSTRY AS object FROM MST_CUSTOMER_INFO i LEFT JOIN MST_CUSTOMER_INFO_ADD a ON i.CUSTOMER_ID = a.CUSTOMER_ID where i.CUSTOMER_TYPE = #{customerType,jdbcType=VARCHAR}
AND (i.CUSTOMER_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) or i.CUSTOMER_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')))
AND i.CUSTOMER_ID = #{initValue,jdbcType=VARCHAR}

		SELECT count(1)
		FROM CREDIT_LINES A
		where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

      and to_char(VDATE,'yyyy-MM-dd')>= #{vdate, jdbcType=VARCHAR}
       and to_char(MDATE,'yyyy-MM-dd')<=#{mdate, jdbcType=VARCHAR}

        and A.PFLSH = #{pflsh,jdbcType=VARCHAR}
		and  A.Hap_Credit_Amt>0
